private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (true) {
        int lead = bb.get(i);
        if (lead < 0x80) {
            sb.append((char) lead);
            return i + 1;
        } else if (lead < 0xC0) {
            i = decodeOctets(i, bb, sb, (byte) 0xC0);
        } else if (lead < 0xE0) {
            i = decodeOctets(i, bb, sb, (byte) 0xE0);
        } else if (lead < 0xF0) {
            i = decodeOctets(i, bb, sb, (byte) 0xF0);
        } else if (lead < 0xF8) {
            i = decodeOctets(i, bb, sb, (byte) 0xF8);
        } else if (lead < 0xFC) {
            i = decodeOctets(i, bb, sb, (byte) 0xFC);
        } else {
            i = decodeOctets(i, bb, sb, (byte) 0xFE);
        }
    }
}

